script:
test("purchases of 60000 and 60000.00 earn 1100.00 across the three bands", function () {
  var expected = {
    rebate: 1100.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 10000.00, amount: 300.00 }
    ]
  };
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 60000 }), expected);
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 60000.00 }), expected);
});

test("exactly 10000.00 stays in the zero percent band and earns 0.00", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.00 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 0.00, amount: 0 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("purchases of 10000.50 earn 0.01 from the two percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.50 }), {
    rebate: 0.01,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 0.50, amount: 0.01 },
      { rate: 0.03, portion: 0, amount: 0 }
    ]
  });
});

test("exactly 50000.00 stays in the two percent band and earns 800.00", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.00 }), {
    rebate: 800.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("one step below 10000.00 earns 0.00 with the whole amount in the zero band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 9999.99 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 9999.99, amount: 0 },
      { rate: 0.02, portion: 0, amount: 0 },
      { rate: 0.03, portion: 0, amount: 0 }
    ]
  });
});

test("one step above 10000.00 rounds a 0.0002 band sum to rebate 0.00", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.01 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 0.01, amount: 0.0002 },
      { rate: 0.03, portion: 0, amount: 0 }
    ]
  });
});

test("one step below 50000.00 rounds 799.9998 to rebate 800.00", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 49999.99 }), {
    rebate: 800.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 39999.99, amount: 799.9998 },
      { rate: 0.03, portion: 0, amount: 0 }
    ]
  });
});

test("one step above 50000.00 rounds 800.0003 to rebate 800.00", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.01 }), {
    rebate: 800.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.01, amount: 0.0003 }
    ]
  });
});

test("a two percent result of 0.0048 rounds to the nearest cent 0.00", function () {
  var result = code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.24 });
  assert.equal(result.rebate, 0.00);
  assert.equal(result.bands[1].portion, 0.24);
  assert.equal(result.bands[1].amount, 0.0048);
  assert.equal(result.bands[2].portion, 0);
});

test("a two percent result of 0.0052 rounds to the nearest cent 0.01", function () {
  var result = code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.26 });
  assert.equal(result.rebate, 0.01);
  assert.equal(result.bands[1].portion, 0.26);
  assert.equal(result.bands[1].amount, 0.0052);
  assert.equal(result.bands[2].portion, 0);
});

test("a three percent total of 801.0047 rounds to the nearest cent 801.00", function () {
  var result = code.calculateQuarterlyRebate({ quarterlyPurchases: 50033.49 });
  assert.equal(result.rebate, 801.00);
  assert.equal(result.bands[2].portion, 33.49);
  assert.equal(result.bands[2].amount, 1.0047);
  assert.equal(result.bands[1].amount, 800);
});

test("a three percent total of 801.0053 rounds to the nearest cent 801.01", function () {
  var result = code.calculateQuarterlyRebate({ quarterlyPurchases: 50033.51 });
  assert.equal(result.rebate, 801.01);
  assert.equal(result.bands[2].portion, 33.51);
  assert.equal(result.bands[2].amount, 1.0053);
  assert.equal(result.bands[1].amount, 800);
});

test("the smallest two decimal purchase of 0.01 earns 0.00", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 0.01 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 0.01, amount: 0 },
      { rate: 0.02, portion: 0, amount: 0 },
      { rate: 0.03, portion: 0, amount: 0 }
    ]
  });
});

test("a purchase of 1 and 1.0 earns 0.00 with the whole amount in the zero band", function () {
  var expected = {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 1.00, amount: 0 },
      { rate: 0.02, portion: 0, amount: 0 },
      { rate: 0.03, portion: 0, amount: 0 }
    ]
  };
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 1 }), expected);
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 1.0 }), expected);
});

test("an unknown field is rejected with its name in the message", function () {
  assert.throws(function () {
    code.calculateQuarterlyRebate({ quarterlyPurchases: 60000.00, note: 1 });
  }, /^unknown field: note$/);
});

test("a missing or non finite quarterlyPurchases is rejected", function () {
  assert.throws(function () {
    code.calculateQuarterlyRebate({});
  }, /^invalid field: quarterlyPurchases$/);
  assert.throws(function () {
    code.calculateQuarterlyRebate({ quarterlyPurchases: NaN });
  }, /^invalid field: quarterlyPurchases$/);
});
